SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(8*10^9);Alarm(800);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");if p eq 0 then k<zet>:=CyclotomicField(3);else k:=GF(p);end if;X:=MDX11(3,18,k);C:=Curve(X);FF:=FunctionField(C);F,mp:=AlgorithmicFunctionField(FF);assert Genus(F)eq 10;B:=BaseField(F);E:=EllipticCurve(X`_E);P:=E!X`_P;Q:=E!X`_Q;print "M318_CUSP_MODEL_FIELD_READY",p,Cputime(tt);
function Units(E,P,Q)ai:=aInvariants(E);fs:=[ai[3],ai[1]^3-27*ai[3]];for j in[1..9]do for b in[0..2]do R:=j*Q+b*P;fs cat:=[R[1],R[2]];end for;R:=j*Q;S:=R+P;Append(~fs,R[1]-S[1]);end for;return fs;end function;
cs:=Cusps(X);fs:=Units(E,P,Q);groups:=AssociativeArray();for c in cs do sig:=[Valuation(f,c):f in fs];if IsDefined(groups,sig)then Append(~groups[sig],c);else groups[sig]:=[c];end if;end for;sigs:=Sort(Setseq(Keys(groups)));old:=eval Read(root cat "paired_p7_group_data.m");assert sigs eq old[2];blocks:=[&+[Divisor(c):c in groups[s]]:s in sigs];ds:=[Degree(D):D in blocks];assert ds eq old[3];print "M318_CUSP_MODEL_BLOCKS_READY",p,#cs,ds,Cputime(tt);
function EC(a)if p eq 0 then return Eltseq(k!a);else return Integers()!(k!a);end if;end function;
function ER(f)return [[EC(c):c in Coefficients(Numerator(f))],[EC(c):c in Coefficients(Denominator(f))]];end function;function EF(f)return [ER(c):c in Eltseq(F!f)];end function;function EP(P)a,b:=TwoGenerators(P);assert ideal<Order(Ideal(P))|a,b>eq Ideal(P);return[*Degree(P),IsFinite(P)select 1 else 0,[EF(a),EF(b)]*];end function;
